class Config {
  private static instance: Config;
  private env: Record<string, any> = {};

  private constructor() {
    this.loadEnv();
  }

  static getInstance(): Config {
    if (!Config.instance) {
      Config.instance = new Config();
    }
    return Config.instance;
  }

  private loadEnv(): void {
    this.env = {
      NODE_ENV: process.env.NODE_ENV || 'development',
      DATABASE_URL: process.env.DATABASE_URL,
      JWT_SECRET: process.env.JWT_SECRET,
      API_PORT: process.env.API_PORT || 3000,
      LOG_LEVEL: process.env.LOG_LEVEL || 'info'
    };
  }

  get<T>(key: string, defaultValue?: T): T {
    const value = this.env[key] ?? defaultValue;
    if (value === undefined) {
      throw new Error(`Environment variable ${key} is not defined`);
    }
    return value;
  }

  getBoolean(key: string): boolean {
    return this.get<string>(key) === 'true';
  }

  getNumber(key: string): number {
    return parseInt(this.get<string>(key), 10);
  }

  isDevelopment(): boolean {
    return this.get('NODE_ENV') === 'development';
  }

  isProduction(): boolean {
    return this.get('NODE_ENV') === 'production';
  }
}

class RateLimiter {
  private attempts = new Map<string, number[]>();

  isAllowed(key: string, maxAttempts: number, windowMs: number): boolean {
    const now = Date.now();
    const windowStart = now - windowMs;

    if (!this.attempts.has(key)) {
      this.attempts.set(key, [now]);
      return true;
    }

    const timestamps = this.attempts.get(key)!;

    // Remove old timestamps outside window
    const validTimestamps = timestamps.filter(t => t > windowStart);

    if (validTimestamps.length < maxAttempts) {
      validTimestamps.push(now);
      this.attempts.set(key, validTimestamps);
      return true;
    }

    return false;
  }

  getRemainingAttempts(key: string, maxAttempts: number, windowMs: number): number {
    const now = Date.now();
    const windowStart = now - windowMs;
    const timestamps = this.attempts.get(key) || [];

    const validCount = timestamps.filter(t => t > windowStart).length;
    return Math.max(0, maxAttempts - validCount);
  }

  reset(key: string): void {
    this.attempts.delete(key);
  }
}

class Queue<T> {
  private items: T[] = [];

  enqueue(item: T): void {
    this.items.push(item);
  }

  dequeue(): T | undefined {
    return this.items.shift();
  }

  peek(): T | undefined {
    return this.items[0];
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  size(): number {
    return this.items.length;
  }

  clear(): void {
    this.items = [];
  }
}

// Async Queue for background tasks
class AsyncQueue<T> {
  private queue = new Queue<T>();
  private processing = false;

  constructor(private processor: (item: T) => Promise<void>) {}

  enqueue(item: T): void {
    this.queue.enqueue(item);
    this.process();
  }

  private async process(): Promise<void> {
    if (this.processing) return;
    this.processing = true;

    while (!this.queue.isEmpty()) {
      const item = this.queue.dequeue();
      if (item) {
        await this.processor(item);
      }
    }

    this.processing = false;
  }
}

type Observer<T> = (value: T) => void;

class Observable<T> {
  private observers: Observer<T>[] = [];
  private value: T;

  constructor(initialValue: T) {
    this.value = initialValue;
  }

  subscribe(observer: Observer<T>): () => void {
    this.observers.push(observer);

    // Return unsubscribe function
    return () => {
      const index = this.observers.indexOf(observer);
      if (index > -1) {
        this.observers.splice(index, 1);
      }
    };
  }

  next(value: T): void {
    this.value = value;
    this.observers.forEach(observer => observer(value));
  }

  getValue(): T {
    return this.value;
  }
}

