interface PaginationParams {
  page: number;
  pageSize: number;
}

interface PaginatedResult<T> {
  data: T[];
  page: number;
  pageSize: number;
  total: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export class Paginator {
  static getPaginationParams(query: any, defaultPageSize = 10): PaginationParams {
    const page = Math.max(1, parseInt(query.page) || 1);
    const pageSize = Math.min(100, parseInt(query.pageSize) || defaultPageSize);

    return { page, pageSize };
  }

  static getOffsetAndLimit(page: number, pageSize: number) {
    return {
      offset: (page - 1) * pageSize,
      limit: pageSize
    };
  }

  static paginateArray<T>(array: T[], page: number, pageSize: number): PaginatedResult<T> {
    const total = array.length;
    const totalPages = Math.ceil(total / pageSize);
    const offset = (page - 1) * pageSize;
    const data = array.slice(offset, offset + pageSize);

    return {
      data,
      page,
      pageSize,
      total,
      totalPages,
      hasNextPage: page < totalPages,
      hasPrevPage: page > 1
    };
  }
}

// Type guards
export function isString(value: unknown): value is string {
  return typeof value === 'string';
}

export function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value);
}

export function isArray<T>(value: unknown): value is T[] {
  return Array.isArray(value);
}

export function isObject(value: unknown): value is object {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export function hasProperty<T extends PropertyKey>(
  obj: unknown,
  prop: T
): obj is Record<T, unknown> {
  return isObject(obj) && prop in obj;
}

export function isInstanceOf<T>(
  value: unknown,
  constructor: new (...args: any[]) => T
): value is T {
  return value instanceof constructor;
}

