export function filterMap<T, U>(
  array: T[],
  callback: (item: T) => U | undefined
): U[] {
  return array
    .map(callback)
    .filter((item): item is U => item !== undefined);
}

export async function filterMapAsync<T, U>(
  array: T[],
  callback: (item: T) => Promise<U | undefined>
): Promise<U[]> {
  const results = await Promise.all(array.map(callback));
  return results.filter((item): item is U => item !== undefined);
}

